import urllib.request,re,concurrent.futures
urls=['https://www.scaleway.com/en/developers/api/registry/','https://www.scaleway.com/en/docs/serverless-containers/how-to/deploy-container/','https://www.scaleway.com/en/docs/serverless-containers/reference-content/containers-limitations/']
def read(url):
 try:
  req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
  s=urllib.request.urlopen(req,timeout=20).read().decode()
  s=re.sub(r'<script\b[^>]*>.*?</script>|<style\b[^>]*>.*?</style>','',s,flags=re.S)
