  return url+'\n'+'\n'.join(hits)
 except Exception as e:return url+' '+str(e)
for result in concurrent.futures.ThreadPoolExecutor(max_workers=3).map(read,urls):print(result+'\n')
PY`,timeout_secs:50}); }

