  await panel.send({ type: 'refresh', token: old });
  await f.commands.get('scalewayAI.openModels')();
  assert.notEqual(panel.token(), old);
  assert.equal(f.panels(), 1);
  panel.dispose();
  await f.commands.get('scalewayAI.openModels')();
  assert.equal(f.panels(), 2);
  f.panelRecords[1].dispose();
});

