export function modelsOverviewHtml(
  webview: vscode.Webview,
  root: vscode.Uri,
  project: string | undefined,
  serverless: ListedModel[],
  dedicated: ListedModel[],
  dedicatedState: string,
): { html: string; token: string } {
  const token = randomBytes(24).toString('hex');
  const rows =
    project === undefined
      ? []
      : [
          ...serverless.filter(
            (row) => row.kind === 'serverless' && row.status !== 'deleted',
          ),
          ...dedicated.filter(
            (row) => row.kind === 'dedicated' && row.status !== 'deleted',
          ),
        ];
  const body =
    '<p class="subtitle">' +
    (project !== undefined
      ? 'Projet : ' + escapeHtml(project)
      : 'Choisissez un projet connecté et un espace de travail approuvé pour voir vos modèles.') +
    '</p>' +
    '<div class="actions"><button data-action="catalog">Ajouter un modèle</button><button data-action="refresh">Actualiser les ressources</button></div>' +
    '<p class="note">Les modèles Serverless sélectionnés utilisent l’inférence hébergée par Scaleway : leur enregistrement dans cet espace de travail ne signifie pas une exécution locale. Cette page ne teste ni votre accès à l’inférence ni la santé du service. Les modèles dédiés sont les déploiements du projet.</p>' +
    (project !== undefined
      ? '<p role="status">Déploiements dédiés : ' +
        escapeHtml(dedicatedState) +
        '</p>'
      : '') +
    '<div class="table-scroll"><table><caption>Mes modèles</caption><thead><tr><th scope="col">Nom</th><th scope="col">Type d’inférence</th><th scope="col">État</th><th scope="col">Action</th></tr></thead><tbody>' +
    rows
      .map(
        (row) =>
          '<tr><td>' +
          escapeHtml(row.label) +
          '</td><td>' +
          (row.kind === 'serverless' ? 'Serverless' : 'Dédié') +
          '</td><td>' +
          escapeHtml(
            row.kind === 'serverless'
              ? 'Accès à l’inférence non testé'
              : (row.status ?? 'Inconnu'),
          ) +
          '</td><td><button data-action="open" data-kind="' +
          row.kind +
          '" data-id="' +
          escapeHtml(row.id) +
          '" aria-label="Ouvrir ' +
          escapeHtml(row.label) +
          '">Ouvrir</button></td></tr>',
      )
      .join('') +
    (rows.length
      ? ''
      : '<tr><td colspan="4">Aucun modèle affiché. Ajoutez une référence depuis le catalogue ou actualisez les déploiements du projet.</td></tr>') +
    '</tbody></table></div>';
  return { html: page(webview, root, 'Modèles', body, token), token };
}

