"  async useServerless(id: string): Promise<ListedModel | undefined> {
    if (!text(id)) return;
    const offered = this.serverless.find((model) => model.id === id);
    if (!(await this.ensureProject())) return;
    const row =
      this.serverless.find((model) => model.id === id) ??
      this.serverlessResources.find((model) => model.id === id) ??
      offered;
    if (
      row?.kind !== 'serverless' ||
      (row.status ?? '')
        .split(' / ')
        .every((status) =>
          ['retired', 'end_of_life', 'eol'].includes(
            status.trim().toLowerCase(),
          ),
        )
    )
      return;
    const key = this.serverlessResourceKey();
    const generation = this.generation;
    const project = this.project;
    if (!key) return;
    const rows = [
      ...this.serverlessResources.filter((model) => model.id !== id),
      {
        id: row.id,
        label: row.label,
        kind: 'serverless' as const,
        status: 'Ajouté à cet espace de travail',
      },
    ];
    if (rows.length > 100) throw new ReadError('workspace_resource_limit');
    await this.write(() =>
      (this.context.workspaceState ?? this.context.globalState).update(
        key,
        rows.map((resource) => ({
          id: resource.id,
          label: resource.label,
          kind: 'serverless',
          status: 'Ajouté à cet espace de travail',
        })),
      ),
    );
    if (
      this.project !== project ||
      generation !== this.generation ||
      !this.connected ||
      !vscode.workspace.isTrusted
