  /** Explicit refresh only; results never persisted as cloud health. */
  async refreshServerlessAvailability(): Promise<void> {
    await this.ready;
    if (!this.serverlessResources.length || this.busy) return;
    if (!(await this.ensureProject())) {
      if (this.connected && vscode.workspace.isTrusted) {
        this.serverlessResources = this.serverlessResources.map((row) => ({
          ...row,
          serverlessAvailability: 'Erreur de vérification',
        }));
        this.changed();
      }
      return;
    }
    let scope: ReturnType<Connection['inferenceScope']>;
    try {
      scope = this.inferenceScope();
    } catch {
      return;
    }
    this.busy = true;
    try {
      const ids = new Set(
        await listServerlessAvailability(scope.authorize(), scope.signal),
      );
      if (!scope.current()) return;
      this.serverlessResources = this.serverlessResources.map((row) => ({
        ...row,
        serverlessAvailability: ids.has(row.id)
          ? 'Disponible'
          : 'Absent de la liste',
      }));
